/* Table For You — Web única; interfaz inspirada en el HTML de Isma.
   Operaciones de datos desde Gradio; Supabase Auth mantiene el JWT y RLS.
   Nunca emplear claves secretas en este archivo. */
'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opt=(rows,value='id',label='name')=>rows.map(x=>`<option value="${esc(x[value])}">${esc(x[label])}</option>`).join('');
const fmt=x=>x==null?'—':String(x);
const dateFmt=d=>d?new Date(d).toLocaleString('es-ES'):'—';
const state={session:null,user:null,profile:null,page:'catalogo',catalogPage:0,catSize:10,catQuery:'',catFilters:{},favPage:0,favSize:5,meetPage:0,meetSize:5,meetQ:'',selectedGame:null,selectedMeet:null,allGames:[],catalogResults:[],favs:new Set(),friendUsers:[],tab:'users'};
let sb;
function toast(t,error=false){const el=$('#toast');el.textContent=t;el.style.background=error?'#982920':'#173642';el.classList.add('show');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>el.classList.remove('show'),4800)}
function errorMessage(e){return String(e?.message||e?.error_description||e||'Error desconocido').replace(/invalid login credentials/i,'Correo o contraseña incorrectos')}
function assert(result){if(result.error)throw result.error;return result.data}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function numberOrNull(x){return x===''||x==null?null:Number(x)}
function checkLogin(){if(!state.user)throw Error('Debes iniciar sesión para realizar esta acción')}
function checkAdmin(){checkLogin();if(state.profile?.role!=='admin')throw Error('No tienes permisos de administración')}
async function withError(fn){try{await fn()}catch(e){console.error(e);toast(errorMessage(e),true)}}
function confirmed(title,text){return new Promise(resolve=>{const d=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;d.showModal();d.addEventListener('close',function onClose(){d.removeEventListener('close',onClose);resolve(d.returnValue==='ok')},{once:true})})}
function badge(text){return `<span class="pill">${esc(text)}</span>`}
function empty(text){return `<div class="empty">${esc(text)}</div>`}
function field(n,label,type='text',val='',extra=''){return `<div class="field"><label for="${n}">${esc(label)}</label><input id="${n}" name="${n}" type="${type}" value="${esc(val??'')}" ${extra}></div>`}
function area(n,label,val=''){return `<div class="field"><label for="${n}">${esc(label)}</label><textarea name="${n}" id="${n}">${esc(val??'')}</textarea></div>`}
function dropdown(n,label,choices,selected){return `<div class="field"><label for="${n}">${esc(label)}</label><select id="${n}" name="${n}">${choices.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`}
function pageTitle(title,desc){return `<div class="eyebrow">TABLE FOR YOU</div><h1>${title}</h1><p class="muted">${desc}</p>`}
function pager(current,size,total,which){const count=Math.max(1,Math.ceil(total/size));return `<div class="pagination"><button class="secondary" data-action="${which}-prev" ${current<=0?'disabled':''}>Anterior</button><span>Página ${current+1} de ${count}</span><button class="secondary" data-action="${which}-next" ${current>=count-1?'disabled':''}>Siguiente</button></div>`}
function selectGameOptions(games,placeholder='Selecciona un juego'){return `<option value="">${esc(placeholder)}</option>`+games.map(g=>`<option value="${g.id}">${esc(g.name)}${g.yearpublished?` (${esc(g.yearpublished)})`:``}</option>`).join('')}
function updateNav(){const login=!!state.user,admin=login&&state.profile?.role==='admin';$$('.protected').forEach(e=>e.hidden=!login);$$('.admin-only').forEach(e=>e.hidden=!admin);$$('.guest-only').forEach(e=>e.hidden=login);$('#session-label').textContent=login?`${state.profile?.display_name||state.profile?.username||state.user.email} · ${admin?'Administrador':'Usuario'}`:'Visitante';$('#account-button').textContent=login?'Cerrar sesión':'Iniciar sesión';$$('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===state.page))}
async function loadIdentity(){const {data:{session}}=await sb.auth.getSession();state.session=session;state.user=session?.user||null;state.profile=null;state.favs=new Set();if(state.user){const r=await sb.from('profiles').select('id,username,display_name,role,suspended_at,bio,reference_location').eq('id',state.user.id).single();if(r.error)throw r.error;state.profile=r.data;if(state.profile.suspended_at){await sb.auth.signOut();state.user=null;state.session=null;state.profile=null;throw Error('Cuenta suspendida');}await loadFavoriteIds()}updateNav()}
async function loadFavoriteIds(){if(!state.user){state.favs=new Set();return}const r=await sb.from('favorites').select('game_id').eq('user_id',state.user.id).limit(10000);state.favs=new Set(assert(r).map(x=>x.game_id))}
async function navigate(page){state.page=page;const protectedPages=['favoritos','recomendaciones','quedadas','comunidad','perfil','notificaciones','propuestas','admin'];if(protectedPages.includes(page)&&!state.user)state.page='acceso';if(state.page==='admin'&&state.profile?.role!=='admin')state.page='catalogo';updateNav();$('#sidebar')?.classList.remove('open');const main=$('#main');main.innerHTML='<div class="loading">Consultando Gradio y Supabase...</div>';try{const renderer={catalogo:renderCatalog,acceso:renderAccess,favoritos:renderFavorites,recomendaciones:renderRecommendations,quedadas:renderMeetups,comunidad:renderCommunity,perfil:renderProfile,notificaciones:renderNotifications,propuestas:renderProposals,admin:renderAdmin}[state.page];await renderer();}catch(e){console.error(e);main.innerHTML=pageTitle('No se pudo cargar', 'Gradio o Supabase han rechazado la operación o no están disponibles')+`<div class="inline-message error">${esc(errorMessage(e))}</div><button data-action="retry" class="secondary">Reintentar</button>`}window.scrollTo({top:0,behavior:'instant'})}
async function searchGames(q='',filters={},page=0,size=10){let query=sb.from('games').select('id,name,description,yearpublished,minplayers,maxplayers,playingtime,average,usersrated,averageweight,minage,boardgamecategory,boardgamemechanic,image_url,is_active',{count:'exact'}).eq('is_active',true);if(q.trim())query=query.ilike('name',`%${q.trim().replace(/[%,]/g,'')}%`);if(filters.players)query=query.lte('minplayers',+filters.players).gte('maxplayers',+filters.players);if(filters.duration)query=query.lte('playingtime',+filters.duration);if(filters.complexity)query=query.lte('averageweight',+filters.complexity);if(filters.category)query=query.ilike('boardgamecategory',`%${filters.category.replace(/[%,]/g,'')}%`);const order=filters.order||'name';query=query.order(order==='popular'?'usersrated':order==='rating'?'average':order==='year'?'yearpublished':'name',{ascending:!['popular','rating','year'].includes(order),nullsFirst:false});const res=await query.range(page*size,page*size+size-1);assert(res);return {rows:res.data,count:res.count||0}}
function gameCard(g){const fav=state.favs.has(g.id);return `<article class="card game">${g.image_url?`<img class="game-cover" src="${esc(g.image_url)}" loading="lazy" alt="Portada de ${esc(g.name)}" onerror="this.style.display='none'">`:'<div class="game-cover"></div>'}<div class="game-body"><div class="row space"><h3>${esc(g.name)}</h3>${badge(g.yearpublished||'Sin año')}</div><div class="meta"><span>♧ ${fmt(g.minplayers)}–${fmt(g.maxplayers)} jugadores</span><span>◷ ${fmt(g.playingtime)} min</span><span>★ ${g.average==null?'Sin valorar':Number(g.average).toFixed(1)+'/10'}</span></div><p class="muted tiny">${esc((g.description||'Sin descripción').slice(0,180))}${g.description?.length>180?'…':''}</p><div class="actions"><button class="primary" data-action="details" data-id="${g.id}">Ver ficha</button>${state.user?`<button class="secondary" data-action="toggle-fav" data-id="${g.id}">${fav?'♥ Quitar favorito':'♡ Añadir favorito'}</button>`:''}</div></div></article>`}
async function renderCatalog(){const result=await searchGames(state.catQuery,state.catFilters,state.catalogPage,state.catSize);state.catalogResults=result.rows;const search=state.catQuery;$('#main').innerHTML=`${pageTitle('Catálogo de juegos','Busca entre los títulos reales de Supabase. Disponible sin iniciar sesión.')}<div class="card"><form id="catalog-form"><div class="form-grid">${field('q','Buscar por nombre','search',search,'placeholder="CATAN"')}${field('players','Número de jugadores','number',state.catFilters.players||'','min="1"')}${field('duration','Tiempo máximo (min)','number',state.catFilters.duration||'','min="1"')}${field('complexity','Complejidad máxima (0–5)','number',state.catFilters.complexity||'','min="0" max="5" step="0.1"')}${field('category','Categoría', 'text',state.catFilters.category||'')}${dropdown('order','Ordenar por',[['name','Nombre'],['rating','Mejor valoración'],['popular','Más populares'],['year','Más recientes']],state.catFilters.order||'name')}</div><div class="actions"><button class="primary" type="submit">Buscar y filtrar</button><button class="secondary" type="button" data-action="catalog-reset">Restablecer</button><button class="secondary" type="button" data-action="catalog-popular">Juegos populares</button>${dropdown('pageSize','Por página',[[5,'5'],[10,'10'],[20,'20']],state.catSize)}</div></form></div><div class="row space"><h2>${result.count} juegos encontrados</h2><span class="muted">${state.user?'Puedes añadir favoritos':'Inicia sesión para guardar favoritos'}</span></div>${result.rows.length?`<div class="grid">${result.rows.map(gameCard).join('')}</div>${pager(state.catalogPage,state.catSize,result.count,'catalog')}`:empty('No se encontraron juegos. Prueba a retirar algún filtro.')}`}
async function renderDetails(id){const g=assert(await sb.from('games').select('*').eq('id',id).single());state.selectedGame=g;let own=null;let reviews=[];if(state.user){const r=await sb.from('game_ratings').select('score,review').eq('user_id',state.user.id).eq('game_id',id).maybeSingle();own=assert(r)}const rr=await sb.from('game_ratings').select('score,review,created_at').eq('game_id',id).order('created_at',{ascending:false}).limit(6);if(!rr.error)reviews=rr.data;$('#main').innerHTML=`<button class="secondary" data-page="catalogo">Volver al catálogo</button><div class="card"><div class="cols2"><div>${g.image_url?`<img class="game-cover" style="height:250px;border-radius:13px" src="${esc(g.image_url)}" alt="Portada">`:empty('Sin portada')}</div><div><span class="eyebrow">FICHA DEL JUEGO</span><h1>${esc(g.name)}</h1><p>${esc(g.description||'Sin descripción')}</p><div class="meta"><span class="chip">Año: ${fmt(g.yearpublished)}</span><span class="chip">Jugadores: ${fmt(g.minplayers)}–${fmt(g.maxplayers)}</span><span class="chip">Duración: ${fmt(g.playingtime)} min</span><span class="chip">Edad: ${fmt(g.minage)}+</span><span class="chip">Complejidad: ${fmt(g.averageweight)}/5</span><span class="chip">★ ${fmt(g.average)}/10 · ${fmt(g.usersrated)} votos</span></div><p class="tiny">Categorías: ${esc(g.boardgamecategory||'—')}</p><p class="tiny">Mecánicas: ${esc(g.boardgamemechanic||'—')}</p>${state.user?`<button class="secondary" data-action="toggle-fav" data-id="${g.id}">${state.favs.has(g.id)?'♥ Quitar favorito':'♡ Añadir favorito'}</button>`:''}</div></div></div>${state.user?`<div class="card"><h2>Tu valoración (1–10)</h2><form id="detail-rating-form"><input type="hidden" name="game_id" value="${g.id}">${dropdown('score','Puntuación',Array.from({length:10},(_,i)=>[i+1,String(i+1)]),own?.score||8)}${area('review','Reseña opcional',own?.review||'')}<button class="primary">${own?'Actualizar':'Guardar'} valoración</button><button type="button" class="secondary" data-action="delete-rating" data-id="${g.id}">Eliminar mi valoración</button></form></div>`:''}<div class="card"><h2>Reseñas recientes</h2>${reviews.length?reviews.map(r=>`<div class="list-item">★ ${r.score}/10 · ${esc(r.review||'Sin comentario')}</div>`).join(''):empty('Sin reseñas de usuarios de Table For You')}</div>`}
async function renderAccess(){const authed=!!state.user;$('#main').innerHTML=pageTitle('Acceso','Regístrate, inicia sesión o cierra tu sesión de forma segura.')+(authed?`<div class="card"><h2>Sesión iniciada</h2><p>${esc(state.user.email)} · ${esc(state.profile?.username)}</p><button class="danger" data-action="logout">Cerrar sesión y limpiar datos</button></div>`:`<div class="cols2"><div class="card"><h2>Iniciar sesión</h2><form id="login-form">${field('email','Correo electrónico','email','','required autocomplete="email"')}${field('password','Contraseña','password','','required autocomplete="current-password"')}<button class="primary">Entrar</button></form></div><div class="card"><h2>Crear cuenta</h2><form id="signup-form">${field('username','Nombre de usuario','text','','required minlength="3" maxlength="40"')}${field('email','Correo electrónico','email','','required')}${field('password','Contraseña','password','','required minlength="8"')}<button class="primary">Registrarme</button></form><p class="help">Recibirás confirmación según la configuración de Supabase Auth.</p></div></div>`)}
async function favoriteToggle(id){checkLogin();if(state.favs.has(id)){assert(await sb.from('favorites').delete().eq('user_id',state.user.id).eq('game_id',id));state.favs.delete(id);toast('Eliminado de favoritos')}else{assert(await sb.from('favorites').insert({user_id:state.user.id,game_id:id}));state.favs.add(id);toast('Añadido a favoritos')}if($('#detail-rating-form')&&state.selectedGame?.id===id)await renderDetails(id);else await navigate(state.page)}
async function saveRating(form){checkLogin();const v=formData(form),id=+v.game_id,score=+v.score;if(score<1||score>10)throw Error('La nota debe estar entre 1 y 10');assert(await sb.from('game_ratings').upsert({game_id:id,user_id:state.user.id,score,review:v.review||null},{onConflict:'user_id,game_id'}));toast('Valoración guardada correctamente');await renderDetails(id)}
async function removeRating(id){checkLogin();const check=assert(await sb.from('game_ratings').select('id').eq('user_id',state.user.id).eq('game_id',id).maybeSingle());if(!check){toast('No hay ninguna valoración tuya para eliminar',true);return}if(!(await confirmed('Eliminar valoración','¿Quieres eliminar tu valoración de este juego?')))return;assert(await sb.from('game_ratings').delete().eq('user_id',state.user.id).eq('game_id',id));toast('Valoración eliminada');await navigate(state.page)}
async function renderFavorites(){checkLogin();await loadFavoriteIds();const {data:items,error,count}=await sb.from('favorites').select('game_id,created_at,games(id,name,average,minplayers,maxplayers,playingtime)',{count:'exact'}).eq('user_id',state.user.id).order('created_at',{ascending:false}).range(state.favPage*state.favSize,state.favPage*state.favSize+state.favSize-1);if(error)throw error;const saved=items||[];$('#main').innerHTML=`${pageTitle('Favoritos y valoraciones','Tus juegos guardados y valoraciones, con datos persistentes.')}<div class="card"><h2>Mis favoritos (${count||0})</h2>${dropdown('favSize','Mostrar por página',[[5,'5'],[10,'10'],[20,'20']],state.favSize)}<div id="fav-list">${saved.length?saved.map(f=>`<label class="list-item row"><input class="fav-check" type="checkbox" value="${f.game_id}" style="width:auto"><span><strong>${esc(f.games?.name||'Juego no disponible')}</strong><span class="muted tiny">★ ${fmt(f.games?.average)} · ${fmt(f.games?.playingtime)} min</span></span><button type="button" class="quiet" data-action="details" data-id="${f.game_id}">Ficha</button></label>`).join(''):empty('Aún no has añadido ningún favorito')}</div>${pager(state.favPage,state.favSize,count||0,'fav')}<button class="danger" data-action="bulk-remove-fav">Eliminar seleccionados</button></div><div class="card"><h2>Valorar cualquier juego</h2><form id="search-rating-form"><div class="row">${field('gameName','Buscar juego por nombre','search','','required placeholder="CATAN"')}<button class="secondary">Buscar</button></div></form><div id="rating-picker"></div></div><div class="card"><h2>Mis valoraciones</h2><div id="my-ratings">${empty('Cargando...')}</div></div>`;const r=await sb.from('game_ratings').select('game_id,score,review,created_at,games(name)').eq('user_id',state.user.id).order('created_at',{ascending:false}).limit(100);$('#my-ratings').innerHTML=r.error?esc(errorMessage(r.error)):(r.data.length?r.data.map(v=>`<div class="list-item row space"><span><strong>${esc(v.games?.name)}</strong>★ ${v.score}/10 · ${esc((v.review||'').slice(0,120))}</span><div class="actions"><button class="secondary" data-action="details" data-id="${v.game_id}">Editar</button><button class="quiet" data-action="delete-rating" data-id="${v.game_id}">Eliminar</button></div></div>`).join(''):empty('Todavía no has valorado juegos'))}
async function renderRecommendations(){checkLogin();$('#main').innerHTML=`${pageTitle('Recomendaciones','Resultados reales según el contexto, el historial y las características del catálogo.')}<div class="card"><h2>Según tu contexto</h2><form id="context-form"><div class="form-grid">${field('players','Nº de jugadores','number','4','required min="1"')}${field('minutes','Tiempo disponible (min)','number','90','required min="1"')}${dropdown('level','Experiencia',[['beginner','Principiante'],['intermediate','Intermedio'],['expert','Experto']],'intermediate')}</div><button class="primary">Buscar juegos compatibles</button></form></div><div class="card"><h2>Juegos similares</h2><form id="similar-form" class="row">${field('q','Buscar un juego','search','','required placeholder="CATAN"')}<button class="secondary">Buscar similares</button></form></div><div class="card"><div class="row"><button class="secondary" data-action="rec-popular">Más populares</button><button class="secondary" data-action="rec-personal">Personalizadas según mis favoritos</button></div><div id="rec-results" class="grid" style="margin-top:12px">${empty('Elige una modalidad para obtener resultados')}</div></div>`}
async function recResults(games){$('#rec-results').innerHTML=games.length?games.map(gameCard).join(''):empty('No se encontraron juegos compatibles')}
// Gradio se utiliza únicamente para el motor Python TF-IDF.
// Las escrituras y la autenticación se hacen directamente mediante Supabase Auth + RLS.
let tfyGradioClient=null;
let tfyGradioUrl=null;
async function tfyCallGradio(mode, ids, limit=10){
  const r=await tfyBridgeRequest({op:'recommend',mode,
    ids:ids.map(x=>Number(x)).filter(Number.isInteger),limit});
  const items=r.items||[];
  if(!Array.isArray(items))throw Error('Respuesta inválida del recomendador');
  const idsValidos=items.map(x=>Number(x.id)).filter(Number.isInteger);
  if(!idsValidos.length)return [];
  const db=await sb.from('games').select('id,name,description,yearpublished,minplayers,maxplayers,playingtime,average,usersrated,averageweight,image_url,boardgamecategory,is_active').in('id',idsValidos).eq('is_active',true);
  const rows=assert(db),lookup=new Map(rows.map(x=>[Number(x.id),x]));
  return idsValidos.map(id=>lookup.get(id)).filter(Boolean);
}
async function modelRecommendations(endpoint){
  // Adaptador de compatibilidad de las llamadas originales del HTML.
  const [pathname,query='']=endpoint.split('?');
  const q=new URLSearchParams(query);
  const mode=pathname==='/similar'?'similar':pathname==='/personalized'?'personalized':null;
  if(!mode)return null;
  const ids=(mode==='similar'?[q.get('game_id')]:String(q.get('ids')||'').split(',')).filter(Boolean);
  try{return await tfyCallGradio(mode,ids,Number(q.get('limit')||10));}
  catch(error){
    console.warn('No se pudo usar el recomendador Python:',error);
    toast('El servidor Python no está disponible; se aplican recomendaciones por catálogo.',true);
    return null;
  }
}

async function recPersonal(){const ids=[...state.favs];if(!ids.length){$('#rec-results').innerHTML=empty('Marca algún favorito para personalizar las recomendaciones');return}const model=await modelRecommendations('/personalized?ids='+encodeURIComponent(ids.slice(0,30).join(','))+'&limit=10');if(model){await recResults(model);return}const f=assert(await sb.from('games').select('id,name,boardgamecategory,averageweight').in('id',ids.slice(0,20)));const words=[...new Set(f.flatMap(g=>String(g.boardgamecategory||'').match(/[A-Za-zÁÉÍÓÚáéíóú ]{4,}/g)||[]))].slice(0,5);const category=words[0]?.replace(/['\[\]]/g,'').trim()||'';const result=await searchGames('',{category,order:'rating'},0,25);await recResults(result.rows.filter(g=>!ids.includes(g.id)).slice(0,10))}
async function renderMeetups(){checkLogin();let q=sb.from('meetups').select('id,title,description,starts_at,location_name,max_participants,status,visibility,organizer_id,planned_duration_minutes',{count:'exact'}).eq('visibility','public').gte('starts_at',new Date().toISOString()).eq('status','open').order('starts_at',{ascending:true});if(state.meetQ.trim())q=q.ilike('title',`%${state.meetQ.trim().replace(/[%,]/g,'')}%`);const r=await q.range(state.meetPage*state.meetSize,state.meetPage*state.meetSize+state.meetSize-1);const m=assert(r);let my=await sb.from('meetups').select('id,title,starts_at,status').eq('organizer_id',state.user.id).order('starts_at',{ascending:false}).limit(100);if(my.error)my={data:[]};$('#main').innerHTML=`${pageTitle('Quedadas y partidas','Organiza encuentros reales, participa y configura sus juegos y equipos.')}<div class="card"><h2>Buscar quedadas públicas</h2><form id="meet-search-form" class="row">${field('q','Buscar por título','search',state.meetQ)}<button class="secondary">Buscar</button></form>${dropdown('meetSize','Mostrar por página',[[5,'5'],[10,'10'],[20,'20']],state.meetSize)}${m.length?m.map(x=>`<div class="list-item row space"><span><strong>${esc(x.title)}</strong><span class="muted tiny">${dateFmt(x.starts_at)} · ${esc(x.location_name)} · aforo ${x.max_participants} · ${esc(x.status)}</span></span><button class="primary" data-action="meet-detail" data-id="${x.id}">Ver quedada</button></div>`).join(''):empty('No hay quedadas que coincidan')}${pager(state.meetPage,state.meetSize,r.count||0,'meet')}</div><div class="cols2"><div class="card"><h2>Acceso a quedada privada</h2><form id="private-form">${field('code','Código de acceso','text','','required')}<button class="secondary">Buscar por código</button></form></div><div class="card"><h2>Mis quedadas organizadas</h2>${my.data.length?my.data.map(x=>`<div class="list-item"><strong>${esc(x.title)}</strong>${dateFmt(x.starts_at)} · ${esc(x.status)} <button class="quiet" data-action="meet-detail" data-id="${x.id}">Gestionar</button></div>`).join(''):empty('No has organizado quedadas')}</div></div><div class="card"><h2>Crear una quedada</h2><p class="help">Selecciona el juego antes de crear la quedada. Ambas operaciones se guardarán juntas en Supabase; si falla alguna, no se creará nada.</p><form id="create-meet-form"><div class="form-grid">${field('title','Título','text','','required')}${field('starts_at','Fecha y hora','datetime-local','','required')}${field('planned_duration','Duración prevista (min)','number','180','required min="1"')}${field('location','Ubicación','text','','required')}${field('capacity','Aforo (incluido organizador)','number','4','required min="1"')}${dropdown('visibility','Visibilidad',[['public','Pública'],['private','Privada']],'public')}<div class="help">En quedadas privadas, el sistema generará el código al crearla.</div>${field('game_search','Buscar juego inicial','search','','placeholder="Escribe CATAN"')}${field('game_duration','Duración del juego inicial (min)','number','90','required min="1"')}</div>${area('description','Descripción (opcional)')}<div class="actions"><button type="button" class="secondary" data-action="find-meet-game">Buscar juego</button></div><div id="meet-game-picker"></div><button class="primary">Crear quedada y añadir juego</button><div id="create-meet-msg"></div></form></div>`}
async function renderMeetDetail(id){checkLogin();state.selectedMeet=id;const meetup=assert(await sb.from('meetups').select('*').eq('id',id).single());const manager=meetup.organizer_id===state.user.id||state.profile?.role==='admin';const [pr,gr]=await Promise.all([sb.from('meetup_participants').select('id,user_id,status').eq('meetup_id',id).order('joined_at'),sb.from('meetup_games').select('id,game_id,play_mode,estimated_duration_minutes,games(name)').eq('meetup_id',id)]);const participants=assert(pr),games=assert(gr);state.currentMeet=meetup;state.currentMeetGames=games;const confirmed=participants.filter(p=>p.status==='confirmed'),joined=participants.find(p=>p.user_id===state.user.id&&p.status!=='left');const persons=await rpc('tfy_meetup_people',{p_meetup_id:id});state.meetupPeople=persons;const peopleById=new Map(persons.map(p=>[p.participant_id,p]));const profiles=participants.map(p=>({...p,label:peopleById.get(p.id)?.display_name||peopleById.get(p.id)?.username||'Participante'}));$('#main').innerHTML=`<button data-page="quedadas" class="secondary">Volver a quedadas</button>${pageTitle(esc(meetup.title),`${dateFmt(meetup.starts_at)} · ${esc(meetup.location_name)}`)}<div class="card"><div class="row space">${badge(meetup.status)}<span>${confirmed.length}/${meetup.max_participants} plazas</span></div><p>${esc(meetup.description)}</p><p>Organizador: ${meetup.organizer_id===state.user.id?'Tú':'Otro usuario'} · ${meetup.visibility==='private'?'Privada':'Pública'}</p>${meetup.visibility==='private'&&manager?`<p>Código de acceso: <strong>${esc(meetup.access_code)}</strong></p>`:''}<div class="actions">${!manager?`${joined?badge('Ya inscrito'):meetup.status==='open'?`<button class="primary" data-action="meet-join" data-id="${id}">Unirse / lista de espera</button>`:''}${joined?`<button class="secondary" data-action="meet-leave" data-id="${id}">Abandonar</button>`:''}`:''}${manager?`<button class="danger" data-action="meet-cancel" data-id="${id}">Cancelar</button><button class="secondary" data-action="meet-close" data-id="${id}">Cerrar quedada</button>`:''}</div></div><div class="cols2"><div class="card"><h2>Participantes y lista de espera</h2>${profiles.map(p=>`<div class="list-item">${esc(p.label)} · ${badge(p.status)}</div>`).join('')||empty('Sin participantes')}</div><div class="card"><h2>Juegos programados</h2>${games.map(g=>`<div class="list-item row space"><span><strong>${esc(g.games?.name)}</strong>${g.estimated_duration_minutes} min · ${esc(g.play_mode)}</span>${manager?`<button class="quiet" data-action="remove-meet-game" data-id="${g.id}">Retirar</button>`:''}</div>`).join('')||empty('No hay juegos programados')}</div></div>${manager?`<div class="card"><h2>Juegos recomendados para la quedada</h2><button class="secondary" data-action="recommend-meet-games">Obtener juegos compatibles con aforo y tiempo disponible</button><div id="meet-recommendations"></div></div><div class="cols2"><div class="card"><h2>Añadir juego</h2><form id="add-meet-game-form"><input type="hidden" name="meetup_id" value="${id}">${field('search','Buscar por nombre','search','','required')}${field('duration','Duración (min)','number','60','required min="1"')}${dropdown('mode','Modo',[['individual','Individual'],['teams','Equipos']],'individual')}<button class="secondary" type="button" data-action="find-add-game">Buscar juego</button><div id="add-game-picker"></div><button class="primary">Añadir a la quedada</button></form></div><div class="card"><h2>Editar quedada</h2><form id="edit-meet-form">${field('title','Título','text',meetup.title,'required')}${field('starts_at','Fecha y hora','datetime-local',new Date(meetup.starts_at).toISOString().slice(0,16),'required')}${field('duration','Duración prevista (min)','number',meetup.planned_duration_minutes,'required min="1"')}${field('location','Ubicación','text',meetup.location_name,'required')}${field('capacity','Aforo','number',meetup.max_participants,'required min="1"')}${area('description','Descripción',meetup.description)}<button class="primary">Guardar cambios</button></form></div></div>`:''}<div class="card"><h2>Chat de la quedada</h2><button class="secondary" data-action="read-chat">Leer / actualizar mensajes</button><div id="chat-feed"></div><form id="chat-send-form" class="row">${field('body','Mensaje','text','','required')}<button class="primary" ${meetup.status!=='open'?'disabled':''}>Enviar</button></form></div><div class="card"><h2>Equipos y resultados</h2><div id="team-section">${games.map(g=>`<div class="list-item"><strong>${esc(g.games?.name)}</strong> · ${esc(g.play_mode)} <button class="secondary" data-action="team-game" data-id="${g.id}">Ver equipos y ganadores</button></div>`).join('')||empty('Añade un juego para gestionar equipos')}</div></div>`;await readChat(false)}
async function readChat(showToast=true){const id=state.selectedMeet;const res=await sb.from('meetup_messages').select('id,message,created_at,sender_id').eq('meetup_id',id).order('created_at',{ascending:true}).limit(200);$('#chat-feed').innerHTML=res.error?`<div class="inline-message error">${esc(errorMessage(res.error))}</div>`:res.data.map(m=>`<div class="list-item"><strong>${esc(m.sender_id===state.user.id?'Tú':(state.meetupPeople||[]).find(p=>p.user_id===m.sender_id)?.display_name||(state.meetupPeople||[]).find(p=>p.user_id===m.sender_id)?.username||'Participante')}</strong><span class="muted tiny"> · ${dateFmt(m.created_at)}</span><p>${esc(m.message)}</p></div>`).join('')||empty('No hay mensajes');if(showToast&&!res.error)toast('Chat actualizado')}
async function renderTeamGame(id){const [teamRes,memberRes,gameRes]=await Promise.all([sb.from('meetup_teams').select('*').eq('meetup_game_id',id),sb.from('meetup_team_members').select('id,team_id,participant_id').eq('meetup_game_id',id),sb.from('meetup_games').select('id,meetup_id,play_mode').eq('id',id).single()]);const teams=assert(teamRes),members=assert(memberRes),game=assert(gameRes),meet=assert(await sb.from('meetups').select('organizer_id').eq('id',game.meetup_id).single());const isManager=meet.organizer_id===state.user.id||state.profile?.role==='admin';const ps=assert(await sb.from('meetup_participants').select('id,user_id,status').eq('meetup_id',game.meetup_id).eq('status','confirmed'));const people=await rpc('tfy_meetup_people',{p_meetup_id:game.meetup_id});const names=new Map(people.map(p=>[p.participant_id,p]));const panel=$('#team-section');panel.innerHTML=`<h3>Juego #${id} · ${esc(game.play_mode)}</h3><h3>Equipos existentes</h3>${teams.map(t=>`<div class="list-item"><strong>${esc(t.name)}</strong>${members.filter(m=>m.team_id===t.id).map(m=>{let p=ps.find(p=>p.id===m.participant_id);return `<span class="chip">${esc(names.get(m.participant_id)?.display_name||names.get(m.participant_id)?.username||'Participante')}</span>`}).join('')||'<span class="help">Sin miembros</span>'}</div>`).join('')||empty('No se han creado equipos')}${isManager?`<div class="divider"></div><form id="create-team-form"><input type="hidden" name="game_id" value="${id}">${field('name','Nombre del equipo','text','','required')}<button class="secondary">Crear equipo</button></form><form id="join-team-form"><input type="hidden" name="game_id" value="${id}">${dropdown('team_id','Equipo',teams.map(t=>[t.id,t.name]))}${dropdown('participant_id','Participante',ps.map(p=>[p.id,names.get(p.id)?.display_name||names.get(p.id)?.username||'Participante']))}<button class="secondary" ${!teams.length?'disabled':''}>Asignar participante</button></form><form id="record-result-form"><input type="hidden" name="game_id" value="${id}">${dropdown('mode','Ganador',[['individual','Jugador individual'],['teams','Equipo']])}${dropdown('participant_id','Jugador ganador',ps.map(p=>[p.id,names.get(p.id)?.display_name||names.get(p.id)?.username||'Participante']))}${dropdown('team_id','Equipo ganador',teams.map(t=>[t.id,t.name]))}<button class="primary">Registrar victoria</button></form>`:''}`}
async function renderCommunity(){checkLogin();$('#main').innerHTML=`${pageTitle('Comunidad y jugadores','Busca perfiles reales, gestiona amistades y consulta mensajes desde sus quedadas.')}<div class="cols2"><div class="card"><h2>Buscar usuarios</h2><form id="user-search-form">${field('search','Nombre de usuario','search','','required minlength="1" placeholder="Escribe un username"')}<button class="primary">Buscar</button></form><div id="user-search-results"></div></div><div class="card"><h2>Mis solicitudes y amistades</h2><button class="secondary" data-action="refresh-friends">Actualizar</button><div id="friends-list"></div><div id="friend-stats"></div></div></div>`;await refreshFriends()}
async function refreshFriends(){const r=await sb.from('friendships').select('id,requester_id,recipient_id,status,created_at').or(`requester_id.eq.${state.user.id},recipient_id.eq.${state.user.id}`).order('created_at',{ascending:false}).limit(150);if(r.error){$('#friends-list').innerHTML=`<div class="inline-message error">${esc(errorMessage(r.error))}</div>`;return}const ids=[...new Set(r.data.flatMap(f=>[f.requester_id,f.recipient_id]))].filter(id=>id!==state.user.id),p=ids.length?await sb.rpc('tfy_friend_names'): {data:[]};const userById=new Map((p.data||[]).map(x=>[x.id,x]));$('#friends-list').innerHTML=r.data.length?r.data.map(f=>{const other=f.requester_id===state.user.id?f.recipient_id:f.requester_id;const name=userById.get(other)?.display_name||userById.get(other)?.username||'Usuario';return `<div class="list-item"><strong>${esc(name)}</strong>${badge(f.status)}${f.status==='pending'&&f.recipient_id===state.user.id?`<div class="actions"><button class="primary" data-action="friend-accept" data-id="${f.id}">Aceptar</button><button class="secondary" data-action="friend-reject" data-id="${f.id}">Rechazar</button></div>`:f.status==='accepted'?`<button class="secondary" data-action="friend-stats" data-id="${other}">Estadísticas</button><button class="quiet" data-action="friend-remove" data-id="${f.id}">Eliminar amistad</button>`:''}</div>`}).join(''):empty('Sin solicitudes o amistades')}
async function renderProfile(){checkLogin();const p=state.profile;const prefRes=await sb.from('user_preferences').select('*').eq('user_id',state.user.id).maybeSingle();const pref=prefRes.error?{}:prefRes.data||{};let stats=await sb.rpc('tfy_profile_stats',{p_user_id:state.user.id});$('#main').innerHTML=`${pageTitle('Mi perfil',`Cuenta: ${esc(state.user.email)}`)}<div class="card"><h2>Datos personales</h2><p class="inline-message">Establece un <strong>nombre de usuario reconocible</strong> para que tus amigos puedan buscarte.</p><form id="profile-form"><div class="form-grid">${field('username','Nombre de usuario','text',p.username,'required minlength="3" maxlength="40"')}${field('display_name','Nombre visible','text',p.display_name||'')}${field('reference_location','Ubicación de referencia','text',p.reference_location||'')}</div>${area('bio','Biografía',p.bio||'')}<button class="primary">Guardar perfil</button></form></div><div class="card"><h2>Preferencias de juegos</h2><form id="preferences-form"><div class="form-grid">${field('preferred_min_players','Jugadores mínimos','number',pref.preferred_min_players||'','min="1"')}${field('preferred_max_players','Jugadores máximos','number',pref.preferred_max_players||'','min="1"')}${field('preferred_max_duration','Duración máxima (min)','number',pref.preferred_max_duration||'','min="1"')}${field('preferred_max_complexity','Complejidad máxima','number',pref.preferred_max_complexity||'','min="0" max="5" step="0.1"')}</div><button class="primary">Guardar preferencias</button></form></div><div class="card"><h2>Mis estadísticas</h2>${stats.error?`<div class="inline-message error">${esc(errorMessage(stats.error))}</div>`:stats.data?.length?`<div class="grid">${Object.entries(stats.data[0]).map(([key,value])=>`<div class="card"><strong>${esc(key)}</strong><h2>${esc(value)}</h2></div>`).join('')}</div>`:empty('Sin estadísticas')}</div>`}
async function renderNotifications(){checkLogin();const r=await sb.from('notifications').select('id,title,body,type,read_at,created_at').eq('user_id',state.user.id).order('created_at',{ascending:false}).limit(100);$('#main').innerHTML=`${pageTitle('Notificaciones','Avisos de quedadas, amistades y cambios relevantes.')}<div class="card"><h2>Mis notificaciones</h2>${r.error?`<div class="inline-message error">${esc(errorMessage(r.error))}</div>`:r.data.map(n=>`<div class="list-item row space"><div><strong>${esc(n.title)}</strong><span class="muted tiny">${dateFmt(n.created_at)} · ${esc(n.type)}</span><p>${esc(n.body||'')}</p></div>${!n.read_at?`<button class="secondary" data-action="notification-read" data-id="${n.id}">Marcar leída</button>`:badge('Leída')}</div>`).join('')||empty('No tienes notificaciones')}</div>`}
async function renderProposals(){checkLogin();const r=await sb.from('game_proposals').select('id,name,status,created_at,review_notes').eq('proposed_by',state.user.id).order('created_at',{ascending:false}).limit(100);$('#main').innerHTML=`${pageTitle('Proponer un juego','Los usuarios proponen y el administrador valida antes de publicarlo.')}<div class="card"><h2>Nueva propuesta</h2><form id="propose-form"><div class="form-grid">${field('name','Nombre del juego','text','','required')}${field('yearpublished','Año','number','','min="0"')}${field('minplayers','Jugadores mínimos','number','','min="0"')}${field('maxplayers','Jugadores máximos','number','','min="1"')}${field('playingtime','Duración (min)','number','','min="0"')}${field('minage','Edad mínima','number','','min="0"')}${field('averageweight','Complejidad 0–5','number','','min="0" max="5" step="0.1"')}${field('boardgamecategory','Categorías','text')}${field('boardgamemechanic','Mecánicas','text')}${field('image_url','URL de portada','url')}</div>${area('description','Descripción')}<button class="primary">Enviar propuesta</button></form></div><div class="card"><h2>Mis propuestas</h2>${r.error?`<div class="inline-message error">${esc(errorMessage(r.error))}</div>`:r.data.map(p=>`<div class="list-item"><strong>${esc(p.name)}</strong>${badge(p.status)} <span class="muted">${esc(p.review_notes||'')}</span></div>`).join('')||empty('No has enviado propuestas')}</div>`}
function gameAdminForm(g={}){return `<form id="admin-game-form"><input type="hidden" name="id" value="${esc(g.id||'')}"><div class="form-grid">${field('name','Nombre','text',g.name||'','required')}${field('yearpublished','Año','number',g.yearpublished||'','min="0"')}${field('minplayers','Jugadores mínimos','number',g.minplayers||'','min="0"')}${field('maxplayers','Jugadores máximos','number',g.maxplayers||'','min="1"')}${field('playingtime','Duración (min)','number',g.playingtime||'','min="0"')}${field('minage','Edad mínima','number',g.minage||'','min="0"')}${field('averageweight','Complejidad','number',g.averageweight||'','min="0" max="5" step="0.1"')}${field('boardgamecategory','Categorías','text',g.boardgamecategory||'')}${field('boardgamemechanic','Mecánicas','text',g.boardgamemechanic||'')}${field('image_url','Portada URL','text',g.image_url||'')}</div>${area('description','Descripción',g.description||'')}<button class="primary">${g.id?'Guardar modificaciones':'Crear juego con ID automático'}</button>${g.id?`<button class="danger" data-action="admin-disable" data-id="${g.id}" type="button">Desactivar juego</button>`:''}</form>`}
async function renderAdmin(){checkAdmin();const [prop,users]=await Promise.all([sb.from('game_proposals').select('*').order('created_at',{ascending:false}).limit(100),sb.from('profiles').select('id,username,display_name,role,suspended_at').order('created_at',{ascending:false}).limit(100)]);$('#main').innerHTML=`${pageTitle('Administración','Solo se habilita a usuarios cuyo rol real en Supabase sea admin.')}<div class="card"><h2>Gestión del catálogo</h2><form id="admin-search-form" class="row">${field('q','Buscar juego por nombre','search','','placeholder="CATAN"')}<button class="secondary">Buscar para editar</button></form><div id="admin-game-picker"></div><div id="admin-game-editor">${gameAdminForm()}</div></div><div class="card"><h2>Propuestas de juegos</h2>${prop.error?`<div class="inline-message error">${esc(errorMessage(prop.error))}</div>`:prop.data.map(p=>`<details class="list-item"><summary><strong>${esc(p.name)} · ${esc(p.status)}</strong></summary><div class="form-grid">${Object.entries(p).filter(([k])=>!['id','proposed_by','reviewed_by'].includes(k)).map(([k,v])=>`<div><span class="help">${esc(k)}</span><p>${esc(v)}</p></div>`).join('')}</div>${p.status==='pending'?`<form class="review-proposal-form"><input type="hidden" name="id" value="${p.id}">${dropdown('decision','Decisión',[['approve','Aceptar'],['reject','Rechazar']])}${field('notes','Observaciones','text')}<button class="primary">Guardar decisión</button></form>`:''}</details>`).join('')||empty('Sin propuestas')}</div><div class="card"><h2>Gestión de usuarios</h2>${users.error?`<div class="inline-message error">${esc(errorMessage(users.error))}</div>`:users.data.map(u=>`<div class="list-item row space"><span><strong>${esc(u.display_name||u.username)}</strong>${esc(u.role)} ${u.suspended_at?'· Suspendido':''}</span>${u.id!==state.user.id?`<button class="secondary" data-action="admin-suspend" data-id="${u.id}" data-suspend="${u.suspended_at?'false':'true'}">${u.suspended_at?'Reactivar':'Suspender'}</button>`:''}</div>`).join('')||empty('Sin usuarios')}</div><div class="card"><h2>Supervisión de quedadas</h2><button class="secondary" data-action="admin-list-meets">Consultar todas las quedadas</button><div id="admin-meet-list"></div></div>`}
function vGame(f){const values=formData(f);const result={name:values.name.trim(),description:values.description||'',yearpublished:numberOrNull(values.yearpublished),minplayers:numberOrNull(values.minplayers),maxplayers:numberOrNull(values.maxplayers),playingtime:numberOrNull(values.playingtime),minage:numberOrNull(values.minage),averageweight:numberOrNull(values.averageweight),boardgamecategory:values.boardgamecategory||'',boardgamemechanic:values.boardgamemechanic||'',image_url:values.image_url||null};if(!result.name)throw Error('Introduce el nombre del juego');if(result.minplayers!=null&&result.maxplayers!=null&&result.minplayers>result.maxplayers)throw Error('El mínimo de jugadores no puede superar el máximo');return result}
async function rpc(name,args){return assert(await sb.rpc(name,args))}
async function handleSubmit(e){const form=e.target;if(!form.id&&!form.classList.contains('review-proposal-form'))return;e.preventDefault();await withError(async()=>{const v=formData(form);switch(form.id||'review-proposal-form'){
case 'login-form':{const r=await sb.auth.signInWithPassword({email:v.email.trim(),password:v.password});assert(r);await loadIdentity();toast('Sesión iniciada correctamente');await navigate('catalogo');break}
case 'signup-form':{if(v.username.trim().length<3)throw Error('El nombre de usuario necesita al menos 3 caracteres');assert(await sb.auth.signUp({email:v.email.trim(),password:v.password,options:{data:{username:v.username.trim()}}}));toast('Registro solicitado. Comprueba si Supabase exige confirmación por correo.');await loadIdentity();await navigate(state.user?'catalogo':'acceso');break}
case 'catalog-form':{state.catQuery=v.q.trim();state.catFilters={players:v.players,duration:v.duration,complexity:v.complexity,category:v.category,order:v.order};state.catSize=+v.pageSize||10;state.catalogPage=0;await navigate('catalogo');break}
case 'detail-rating-form':await saveRating(form);break;
case 'search-rating-form':{if(!v.gameName.trim())throw Error('Escribe el nombre del juego');const r=await searchGames(v.gameName,{},0,12);$('#rating-picker').innerHTML=r.rows.length?r.rows.map(g=>`<div class="list-item row space"><strong>${esc(g.name)}</strong><button class="primary" data-action="details" data-id="${g.id}">Valorar</button></div>`).join(''):empty('No se ha encontrado ningún juego');break}
case 'context-form':{const levels={beginner:2,intermediate:3.5,expert:5};const r=await searchGames('',{players:v.players,duration:v.minutes,complexity:levels[v.level],order:'rating'},0,10);await recResults(r.rows);break}
case 'similar-form':{const r=await searchGames(v.q,{},0,5);if(!r.rows.length)throw Error('No existe ese juego');const anchor=r.rows[0];const model=await modelRecommendations('/similar?game_id='+anchor.id+'&limit=10');if(model){await recResults(model);break}const token=String(anchor.boardgamecategory||'').replace(/[\[\]'"\\]/g,'').split(',')[0]?.trim()||'';const sim=await searchGames('',{category:token,order:'rating'},0,18);await recResults(sim.rows.filter(g=>g.id!==anchor.id).slice(0,10));break}
case 'meet-search-form':state.meetQ=v.q.trim();state.meetPage=0;await navigate('quedadas');break;
case 'private-form':{const results=await rpc('tfy_find_private_meetup',{p_access_code:v.code.trim()});if(!results.length){toast('No se encontró una quedada privada con ese código',true);return}state.privateJoinCode=v.code.trim();const prior=await sb.from('meetup_participants').select('id').eq('meetup_id',results[0].id).eq('user_id',state.user.id).in('status',['confirmed','waitlist']).maybeSingle();if(!prior.data){const status=await rpc('tfy_join_meetup',{p_meetup_id:results[0].id,p_access_code:state.privateJoinCode});toast(status==='waitlist'?'Acceso correcto; estás en lista de espera':'Acceso correcto a la quedada privada')}await renderMeetDetail(results[0].id);break}
case 'create-meet-form':{checkLogin();const selected=$('#create-meet-form [name="game_id"]')?.value;const game_id=+selected;if(!game_id)throw Error('Busca y selecciona el juego inicial antes de crear la quedada');const starts_at=new Date(v.starts_at).toISOString();if(new Date(starts_at)<=new Date())throw Error('La fecha debe ser futura');const created=await rpc('tfy_create_meetup_with_game',{p_title:v.title,p_starts_at:starts_at,p_duration:+v.planned_duration,p_location:v.location,p_capacity:+v.capacity,p_description:v.description||'',p_visibility:v.visibility,p_game_id:game_id,p_game_duration:+v.game_duration,p_game_mode:'individual'});const id=created[0].meetup_id;if(created[0].access_code)toast('Quedada privada creada; guarda su código de acceso');toast('Quedada creada con su juego inicial');await renderMeetDetail(id);break}
case 'add-meet-game-form':{const g=+v.game_id;if(!g)throw Error('Busca y selecciona un juego');await rpc('tfy_add_meetup_game',{p_meetup_id:+v.meetup_id,p_game_id:g,p_duration:+v.duration,p_mode:v.mode});toast('Juego añadido');await renderMeetDetail(+v.meetup_id);break}
case 'edit-meet-form':{const id=state.selectedMeet;await rpc('tfy_edit_meetup',{p_meetup_id:id,p_title:v.title,p_starts_at:new Date(v.starts_at).toISOString(),p_duration:+v.duration,p_location:v.location,p_capacity:+v.capacity,p_description:v.description||'',p_latitude:null,p_longitude:null});toast('Quedada actualizada');await renderMeetDetail(id);break}
case 'chat-send-form':{const body=v.body?.trim();if(!body)throw Error('Escribe un mensaje');assert(await sb.from('meetup_messages').insert({meetup_id:state.selectedMeet,sender_id:state.user.id,message:body}));form.reset();await readChat(false);toast('Mensaje enviado');break}
case 'create-team-form':{await rpc('tfy_create_team',{p_meetup_game_id:+v.game_id,p_name:v.name});toast('Equipo creado');await renderTeamGame(+v.game_id);break}
case 'join-team-form':{await rpc('tfy_assign_team_member',{p_meetup_game_id:+v.game_id,p_team_id:+v.team_id,p_participant_id:+v.participant_id});toast('Participante asignado');await renderTeamGame(+v.game_id);break}
case 'record-result-form':{const individual=v.mode==='individual';await rpc('tfy_record_game_result',{p_meetup_game_id:+v.game_id,p_winning_participant_id:individual?+v.participant_id:null,p_winning_team_id:individual?null:+v.team_id});toast(individual?'Victoria individual registrada':'Victoria del equipo registrada');await renderTeamGame(+v.game_id);break}
case 'user-search-form':{if(!v.search.trim()){ $('#user-search-results').innerHTML=empty('Es necesario indicar un nombre de usuario; no se puede buscar en blanco.');return}const r=await rpc('tfy_user_directory',{p_search:v.search.trim()});const others=r.filter(u=>u.id!==state.user.id);$('#user-search-results').innerHTML=others.length?others.map(u=>`<div class="list-item row space"><span><strong>${esc(u.display_name||u.username)}</strong><span class="muted">@${esc(u.username)}</span></span><button class="secondary" data-action="send-friend" data-id="${u.id}">Enviar solicitud</button></div>`).join(''):empty('No se ha encontrado ningún usuario con ese nombre');break}
case 'profile-form':{if(v.username.trim().length<3)throw Error('Username mínimo 3 caracteres');const values={username:v.username.trim(),display_name:v.display_name.trim()||null,reference_location:v.reference_location.trim()||null,bio:v.bio||null};assert(await sb.from('profiles').update(values).eq('id',state.user.id));await loadIdentity();toast('Perfil actualizado');await navigate('perfil');break}
case 'preferences-form':{const values={user_id:state.user.id,preferred_min_players:numberOrNull(v.preferred_min_players),preferred_max_players:numberOrNull(v.preferred_max_players),preferred_max_duration:numberOrNull(v.preferred_max_duration),preferred_max_complexity:numberOrNull(v.preferred_max_complexity)};assert(await sb.from('user_preferences').upsert(values,{onConflict:'user_id'}));toast('Preferencias actualizadas');break}
case 'propose-form':{const values=vGame(form);const r=await sb.from('game_proposals').insert({...values,proposed_by:state.user.id});assert(r);toast('Propuesta enviada a revisión');await navigate('propuestas');break}
case 'admin-search-form':{checkAdmin();const r=await searchGames(v.q,{},0,20);$('#admin-game-picker').innerHTML=r.rows.map(g=>`<div class="list-item row space"><span>${esc(g.name)}</span><button class="secondary" data-action="admin-edit" data-id="${g.id}">Editar</button></div>`).join('')||empty('No se encontró ese juego');break}
case 'admin-game-form':{checkAdmin();const values=vGame(form);if(v.id){assert(await sb.from('games').update(values).eq('id',+v.id));toast('Juego modificado')}else{assert(await sb.from('games').insert({...values,source:'admin',is_active:true}));toast('Juego creado. ID generado por PostgreSQL')}await navigate('admin');break}
case 'review-proposal-form':{checkAdmin();await rpc('tfy_review_proposal',{p_proposal_id:+v.id,p_approve:v.decision==='approve',p_notes:v.notes||''});toast(`Propuesta ${v.decision==='approve'?'aprobada':'rechazada'}`);await navigate('admin');break}
}})}
async function searchGamePicker(inputId,outputId){const val=$(inputId)?.value||'';if(!val.trim())throw Error('Introduce el nombre de un juego');const r=await searchGames(val.trim(),{},0,15);$(outputId).innerHTML=r.rows.length?`<div class="field"><label>Selecciona el juego del catálogo</label><select name="game_id" required>${selectGameOptions(r.rows)}</select></div>`:empty('No se encontró ningún juego')}
async function clickAction(e){const nav=e.target.closest('[data-page]');if(nav){e.preventDefault();await navigate(nav.dataset.page);return}const btn=e.target.closest('[data-action]');if(!btn)return;e.preventDefault();await withError(async()=>{const act=btn.dataset.action,id=+btn.dataset.id;switch(act){case 'retry':await navigate(state.page);break;case 'logout':{await sb.auth.signOut();state.user=null;state.session=null;state.profile=null;state.selectedGame=null;state.selectedMeet=null;state.favs=new Set();state.catalogResults=[];state.friendUsers=[];state.catQuery='';state.catFilters={};state.page='catalogo';updateNav();toast('Sesión cerrada; datos personales limpiados');await navigate('catalogo');break}
case 'details':await renderDetails(id);break;case 'toggle-fav':await favoriteToggle(id);break;case 'delete-rating':await removeRating(id);break;
case 'catalog-popular':state.catQuery='';state.catFilters={order:'popular'};state.catalogPage=0;await navigate('catalogo');break;case 'catalog-reset':state.catQuery='';state.catFilters={};state.catalogPage=0;await navigate('catalogo');break;
case 'catalog-prev':state.catalogPage=Math.max(0,state.catalogPage-1);await navigate('catalogo');break;case 'catalog-next':state.catalogPage++;await navigate('catalogo');break;
case 'fav-prev':state.favPage=Math.max(0,state.favPage-1);await navigate('favoritos');break;case 'fav-next':state.favPage++;await navigate('favoritos');break;
case 'bulk-remove-fav':{const ids=$$('.fav-check:checked').map(x=>+x.value);if(!ids.length){toast('Selecciona al menos un favorito',true);return}if(!(await confirmed('Eliminar favoritos',`Se eliminarán ${ids.length} juegos de tus favoritos. ¿Continuar?`)))return;assert(await sb.from('favorites').delete().eq('user_id',state.user.id).in('game_id',ids));toast(`${ids.length} favoritos eliminados`);await navigate('favoritos');break}
case 'rec-popular':{const r=await searchGames('',{order:'popular'},0,10);await recResults(r.rows);break}case 'rec-personal':await recPersonal();break;
case 'meet-prev':state.meetPage=Math.max(0,state.meetPage-1);await navigate('quedadas');break;case 'meet-next':state.meetPage++;await navigate('quedadas');break;
case 'meet-detail':await renderMeetDetail(id);break;
case 'find-meet-game':await searchGamePicker('#create-meet-form [name="game_search"]','#meet-game-picker');break;
case 'recommend-meet-games':{const m=state.currentMeet;const existing=state.currentMeetGames||[];const used=existing.reduce((a,g)=>a+(+g.estimated_duration_minutes||0),0);const remaining=m.planned_duration_minutes-used;if(remaining<=0){$('#meet-recommendations').innerHTML=empty('No hay tiempo disponible');return}const g=await searchGames('',{players:m.max_participants,duration:remaining,order:'rating'},0,18);const ex=new Set(existing.map(x=>x.game_id));const candidates=g.rows.filter(x=>!ex.has(x.id)).slice(0,10);$('#meet-recommendations').innerHTML=candidates.length?candidates.map(x=>`<div class="list-item row space"><span><strong>${esc(x.name)}</strong><span class="muted tiny">${x.playingtime} min · ${x.minplayers}–${x.maxplayers} jugadores</span></span><button class="primary" data-action="meet-add-recommended" data-id="${x.id}" data-duration="${x.playingtime}">Añadir</button></div>`).join(''):empty('No hay juegos compatibles con este aforo y tiempo');break}case 'meet-add-recommended':{const duration=+btn.dataset.duration;if(!duration)throw Error('Este juego no tiene duración válida');await rpc('tfy_add_meetup_game',{p_meetup_id:state.selectedMeet,p_game_id:id,p_duration:duration,p_mode:'individual'});toast('Juego recomendado añadido');await renderMeetDetail(state.selectedMeet);break}case 'find-add-game':await searchGamePicker('#add-meet-game-form [name="search"]','#add-game-picker');break;
case 'meet-join':{const status=await rpc('tfy_join_meetup',{p_meetup_id:id,p_access_code:state.privateJoinCode||null});toast(status==='waitlist'?'Apuntado a la lista de espera':'Te has unido a la quedada');await renderMeetDetail(id);break}
case 'meet-leave':{if(!(await confirmed('Abandonar quedada','¿Quieres abandonar esta quedada?')))return;await rpc('tfy_leave_meetup',{p_meetup_id:id});toast('Has abandonado la quedada');await renderMeetDetail(id);break}
case 'meet-cancel':{if(!(await confirmed('Cancelar quedada','Esta operación notificará la cancelación a los participantes.')))return;await rpc('tfy_cancel_meetup',{p_meetup_id:id});toast('Quedada cancelada');await renderMeetDetail(id);break}
case 'meet-close':{if(!(await confirmed('Cerrar quedada','Se cerrará con los resultados registrados. ¿Continuar?')))return;await rpc('tfy_close_meetup',{p_meetup_id:id});toast('Quedada celebrada y cerrada');await renderMeetDetail(id);break}
case 'remove-meet-game':{if(!(await confirmed('Retirar juego','¿Quieres quitar este juego de la quedada?')))return;await rpc('tfy_remove_meetup_game',{p_meetup_game_id:id});toast('Juego retirado de la quedada');await renderMeetDetail(state.selectedMeet);break}
case 'read-chat':await readChat();break;case 'team-game':await renderTeamGame(id);break;
case 'refresh-friends':await refreshFriends();break;case 'friend-stats':{const r=await rpc('tfy_profile_stats',{p_user_id:btn.dataset.id});$('#friend-stats').innerHTML=`<div class="card"><h3>Estadísticas de tu amistad</h3>${Object.entries(r[0]||{}).map(([k,v])=>`<span class="chip">${esc(k)}: ${esc(v)}</span>`).join('')}</div>`;break}case 'notification-read':{assert(await sb.from('notifications').update({read_at:new Date().toISOString()}).eq('id',id).eq('user_id',state.user.id));toast('Notificación marcada como leída');await navigate('notificaciones');break}
case 'send-friend':{assert(await sb.from('friendships').insert({requester_id:state.user.id,recipient_id:btn.dataset.id,status:'pending'}));toast('Solicitud de amistad enviada');await refreshFriends();break}
case 'friend-accept':case 'friend-reject':{const status=act==='friend-accept'?'accepted':'rejected';assert(await sb.from('friendships').update({status,responded_at:new Date().toISOString()}).eq('id',id).eq('recipient_id',state.user.id));toast(`Solicitud ${status==='accepted'?'aceptada':'rechazada'}`);await refreshFriends();break}
case 'friend-remove':{if(!(await confirmed('Eliminar amistad','Se eliminará esta amistad.')))return;assert(await sb.from('friendships').delete().eq('id',id));toast('Amistad eliminada');await refreshFriends();break}
case 'admin-edit':{checkAdmin();const g=assert(await sb.from('games').select('*').eq('id',id).single());$('#admin-game-editor').innerHTML=gameAdminForm(g);$('#admin-game-editor').scrollIntoView({behavior:'smooth'});break}
case 'admin-disable':{checkAdmin();if(!(await confirmed('Desactivar juego','El juego dejará de aparecer en el catálogo, sin borrar su historial.')))return;assert(await sb.from('games').update({is_active:false}).eq('id',id));toast('Juego desactivado');await navigate('admin');break}
case 'admin-suspend':{checkAdmin();if(!(await confirmed('Modificar cuenta',`¿${btn.dataset.suspend==='true'?'Suspender':'Reactivar'} esta cuenta?`)))return;await rpc('tfy_admin_set_suspended',{p_user_id:btn.dataset.id,p_suspended:btn.dataset.suspend==='true'});toast('Estado de la cuenta actualizado');await navigate('admin');break}
case 'admin-list-meets':{checkAdmin();const r=await sb.from('meetups').select('id,title,status,starts_at').order('starts_at',{ascending:false}).limit(100);assert(r);$('#admin-meet-list').innerHTML=r.data.map(m=>`<div class="list-item row space"><span><strong>${esc(m.title)}</strong>${dateFmt(m.starts_at)} · ${esc(m.status)}</span><button class="secondary" data-action="meet-detail" data-id="${m.id}">Supervisar</button></div>`).join('')||empty('Sin quedadas');break}
}})}
function changeAction(e){const target=e.target;switch(target.id){case 'favSize':state.favSize=+target.value;state.favPage=0;withError(()=>navigate('favoritos'));break;case 'meetSize':state.meetSize=+target.value;state.meetPage=0;withError(()=>navigate('quedadas'));break}}
async function init(){try{if(!window.supabase?.createClient)throw Error('No se pudo cargar la librería de Supabase. Revisa tu conexión a Internet.');const cfg=window.TFY_CONFIG;if(!cfg?.supabaseUrl||!cfg?.supabasePublishableKey?.startsWith('sb_publishable_'))throw Error('config.js necesita la clave publicable de Supabase');sb=window.supabase.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey,{auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:true}});tfyEnableGradioBackend(sb);document.addEventListener('click',e=>{clickAction(e).catch(err=>toast(errorMessage(err),true))});document.addEventListener('submit',e=>{handleSubmit(e).catch(err=>toast(errorMessage(err),true))});document.addEventListener('change',changeAction);$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#account-button').addEventListener('click',()=>withError(async()=>{if(state.user){await sb.auth.signOut();state.user=null;state.session=null;state.profile=null;state.selectedGame=null;state.selectedMeet=null;state.favs=new Set();state.catalogResults=[];state.friendUsers=[];state.catQuery='';state.catFilters={};await navigate('catalogo')}else await navigate('acceso')}));await loadIdentity();await navigate('catalogo')}catch(e){console.error(e);$('#main').innerHTML=`<div class="card"><h2>Problema al iniciar</h2><p>${esc(errorMessage(e))}</p><p>Comprueba config.js y que la API de Supabase sea accesible.</p></div>`}}
document.addEventListener('DOMContentLoaded',init);
